import{_ as a,o as n,c as p,a2 as t}from"./chunks/framework.C4u7U0Dw.js";const d=JSON.parse('{"title":"教育培训提示词模板","description":"教育培训行业的 5 条提示词模板：课程介绍与招生、教案设计、作业批改反馈、家长沟通、学习报告。","frontmatter":{"title":"教育培训提示词模板","description":"教育培训行业的 5 条提示词模板：课程介绍与招生、教案设计、作业批改反馈、家长沟通、学习报告。"},"headers":[],"relativePath":"community/prompts/教育培训.md","filePath":"community/prompts/教育培训.md"}'),e={name:"community/prompts/教育培训.md"};function o(l,s,i,c,r,u){return n(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="🎓-教育培训-·-5-条提示词模板" tabindex="-1">🎓 教育培训 · 5 条提示词模板 <a class="header-anchor" href="#🎓-教育培训-·-5-条提示词模板" aria-label="Permalink to &quot;🎓 教育培训 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>这行的活有两头：<strong>一头是教学</strong>（备课、批改、上课），<strong>一头是招生与家长</strong>（介绍、沟通、续费）。 很多人教学很行，但两头的时间被撕碎了。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我带的是【什么学段 / 什么科目 / 什么班型 / 学员什么基础】。</span></span>
<span class="line"><span>帮我产出【教案 / 反馈 / 沟通话术】，篇幅【…】。</span></span>
<span class="line"><span>按【考纲 / 我的教学风格 / 你们机构的规矩】来；具体到人的信息用我给的，别编。</span></span></code></pre></div><hr><h2 id="_1-·-课程介绍-→-让家长看懂-我孩子能得到什么" tabindex="-1">1 · 课程介绍 → 让家长看懂&quot;我孩子能得到什么&quot; <a class="header-anchor" href="#_1-·-课程介绍-→-让家长看懂-我孩子能得到什么" aria-label="Permalink to &quot;1 · 课程介绍 → 让家长看懂&quot;我孩子能得到什么&quot;&quot;">​</a></h2><p><strong>什么时候用</strong>：写招生简章、朋友圈介绍、课程顾问话术，总在写&quot;名师执教、小班教学&quot;这种谁都会写的话。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的课程：【科目 / 学段 / 班型人数 / 总课时 / 价格】</span></span>
<span class="line"><span>学员现状：【典型学员是什么水平，有什么典型问题】</span></span>
<span class="line"><span>我真正比别人强在哪：【1-2 条，必须是真的，例如&quot;每次课都留 15 分钟一对一答疑&quot;】</span></span>
<span class="line"><span>家长最担心什么：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写三份不同长度的介绍：</span></span>
<span class="line"><span>① 50 字版（发朋友圈 / 群）</span></span>
<span class="line"><span>② 200 字版（公众号 / 介绍页）</span></span>
<span class="line"><span>③ 一段 30 秒的口头介绍（顾问照着念）</span></span>
<span class="line"><span>每份都要：先写&quot;孩子的具体处境&quot;，再写&quot;我们怎么解决&quot;，最后写&quot;能看见的结果形式（不是分数承诺）&quot;。</span></span>
<span class="line"><span>规矩：不许出现&quot;提分快&quot;&quot;保过&quot;&quot;名师&quot;这类词，除非我有真实可查的依据；不许承诺分数。</span></span></code></pre></div><p><strong>它给你</strong>：三份长度的介绍。<strong>&quot;先说孩子的处境&quot;是转化的关键</strong>，比堆优势有用。</p><hr><h2 id="_2-·-一节课的教案-含时间轴和提问设计" tabindex="-1">2 · 一节课的教案（含时间轴和提问设计） <a class="header-anchor" href="#_2-·-一节课的教案-含时间轴和提问设计" aria-label="Permalink to &quot;2 · 一节课的教案（含时间轴和提问设计）&quot;">​</a></h2><p><strong>什么时候用</strong>：你要上的一节课，内容你熟，但&quot;怎么讲得不困、怎么知道他们懂了&quot;要花时间设计。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这节课：【科目 / 学段 / 课题 / 时长（例如 45 分钟）】</span></span>
<span class="line"><span>学员水平：【…】，班上大概【…】人</span></span>
<span class="line"><span>这节课的目标：【学生下课后必须会做什么（可检验的）】</span></span>
<span class="line"><span>我手里有的材料：【教材 / 例题 / 习题，粘贴关键内容】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我设计教案，必须包含：</span></span>
<span class="line"><span>① 时间轴（分钟级切分，含&quot;开场 3 分钟怎么抓注意力&quot;）</span></span>
<span class="line"><span>② 每段的&quot;老师做什么 / 学生做什么&quot;两列</span></span>
<span class="line"><span>③ 至少 4 个提问，并标明每个问题是&quot;查记忆&quot;还是&quot;逼思考&quot;</span></span>
<span class="line"><span>④ 一个&quot;全班都会但其实是假懂&quot;的检查点（容易混淆的地方）</span></span>
<span class="line"><span>⑤ 最后 3 分钟的收尾与作业布置</span></span>
<span class="line"><span>规矩：不要用我材料里没有的知识点；不确定学段难度是否合适的地方标出来。</span></span></code></pre></div><p><strong>它给你</strong>：一份带时间轴的教案。<strong>第④条&quot;假懂检查点&quot;最值钱</strong>。</p><hr><h2 id="_3-·-作业批改-批量评语-个性化反馈" tabindex="-1">3 · 作业批改：批量评语 + 个性化反馈 <a class="header-anchor" href="#_3-·-作业批改-批量评语-个性化反馈" aria-label="Permalink to &quot;3 · 作业批改：批量评语 + 个性化反馈&quot;">​</a></h2><p><strong>什么时候用</strong>：一堆作业要批，你想给每个人写一句有用的话，但时间不够。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是我这次作业的情况：</span></span>
<span class="line"><span>① 普遍性的问题：【…（照实写）】</span></span>
<span class="line"><span>② 下面 5 个学生的具体情况（我用代号代替姓名）：</span></span>
<span class="line"><span>学生 A：【错在哪 / 漏了什么 / 值得表扬的一点】</span></span>
<span class="line"><span>学生 B：【…】</span></span>
<span class="line"><span>（依次）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 写一段&quot;全班共性问题&quot;的讲评（不超过 150 字，先讲清楚错在哪，再讲怎么做对）</span></span>
<span class="line"><span>② 给每个学生写 2 句话反馈：第一句具体说他的问题或进步，第二句给一个可执行的小动作</span></span>
<span class="line"><span>规矩：不评价孩子的性格和能力（不说&quot;粗心&quot;&quot;聪明&quot;&quot;态度不好&quot;），只说行为；不要用空洞的&quot;加油&quot;占位置。</span></span></code></pre></div><p><strong>它给你</strong>：一段讲评 + 每人两句。<strong>&quot;只说行为不评价人&quot;这条务必保留</strong>——写对了，家长会感谢你。</p><hr><h2 id="_4-·-家长沟通-进步怎么说、问题怎么说、续费怎么开口" tabindex="-1">4 · 家长沟通：进步怎么说、问题怎么说、续费怎么开口 <a class="header-anchor" href="#_4-·-家长沟通-进步怎么说、问题怎么说、续费怎么开口" aria-label="Permalink to &quot;4 · 家长沟通：进步怎么说、问题怎么说、续费怎么开口&quot;">​</a></h2><p><strong>什么时候用</strong>：要给家长发消息，尤其是&quot;报忧&quot;和&quot;谈续费&quot;，措辞很费心。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>家长情况：【孩子年级 / 家长的性格和关注点 / 之前沟通过什么】</span></span>
<span class="line"><span>我要说的事：【孩子最近的真实表现，好的和不好的都写】</span></span>
<span class="line"><span>我的目的：【单纯反馈 / 提醒注意 / 谈续费 / 处理不满】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写一条微信消息，三段式：</span></span>
<span class="line"><span>① 先给一个具体的事实（细节，不是评价）</span></span>
<span class="line"><span>② 再说问题或建议（给一个家长今晚在家就能做的小动作）</span></span>
<span class="line"><span>③ 最后给一个明确的下一步（我下节课会怎么做 / 什么时候再反馈）</span></span>
<span class="line"><span>长度：150 字以内，适合微信直接发，不要太&quot;官方&quot;。</span></span>
<span class="line"><span>如果是要谈续费，另外给我一个&quot;不提钱的钩子版本&quot;。</span></span>
<span class="line"><span>规矩：不许编孩子的表现，只写我给的；不能承诺保证效果。</span></span></code></pre></div><p><strong>它给你</strong>：一条可直接发的消息（约 150 字）。<strong>&quot;一个家长今晚就能做的小动作&quot;是这行的口碑来源。</strong></p><hr><h2 id="_5-·-阶段学习报告-给家长看的那一页纸" tabindex="-1">5 · 阶段学习报告（给家长看的那一页纸） <a class="header-anchor" href="#_5-·-阶段学习报告-给家长看的那一页纸" aria-label="Permalink to &quot;5 · 阶段学习报告（给家长看的那一页纸）&quot;">​</a></h2><p><strong>什么时候用</strong>：期中、期末、结课，要出一份报告，比&quot;分数+评语&quot;更有说服力。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>学员：【代号 + 学段 / 科目 / 学了多久 / 课时数】</span></span>
<span class="line"><span>开始的水平：【…（用具体表现描述，例如&quot;有理数计算经常出错&quot;）】</span></span>
<span class="line"><span>现在的水平：【…】</span></span>
<span class="line"><span>过程中的记录：【哪几次课有明显变化 / 什么题类型突破了 / 什么还没解决】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我生成一份一页纸学习报告：</span></span>
<span class="line"><span>① 起点：进来时是什么状态（用具体表现，不用分数）</span></span>
<span class="line"><span>② 变化：中间发生了什么（3 个节点，带时间和具体事例）</span></span>
<span class="line"><span>③ 现在：能做什么、还不能做什么（各写 2 条，诚实）</span></span>
<span class="line"><span>④ 下一步建议：下阶段 3 个重点 + 家里可以配合的 1 件事</span></span>
<span class="line"><span>⑤ 一段不超过 80 字的&quot;我看到的这个孩子&quot;（写行为与特点，不写评价套话）</span></span>
<span class="line"><span>规矩：所有内容必须来自我给的记录，不许补；没有的节点就不写。</span></span></code></pre></div><p><strong>它给你</strong>：一份能让家长觉得&quot;老师真的在看我孩子&quot;的报告。</p><hr><h2 id="⚠️-这行的三条红线" tabindex="-1">⚠️ 这行的三条红线 <a class="header-anchor" href="#⚠️-这行的三条红线" aria-label="Permalink to &quot;⚠️ 这行的三条红线&quot;">​</a></h2><ol><li><strong>不许承诺分数、名次、录取</strong>。这是这行最容易踩的雷，也是 AI 最爱帮你说的话。</li><li><strong>不要给&quot;诊断式&quot;标签</strong>：多动、注意力缺陷、学习障碍这类词，轮不到我们下判断。发现异常，建议家长找专业机构。</li><li><strong>未成年人信息要保护</strong>：姓名、照片、成绩、家庭情况，给 AI 处理前一律用代号，别把原表直接粘进去。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/房产与中介.html">房产与中介</a></strong></p>`,34)])])}const q=a(e,[["render",o]]);export{d as __pageData,q as default};
